import{_ as a,o,c as t,a2 as s}from"./chunks/framework.DncwoWA8.js";const i="/projects/ai-skills/diagrams/specify-observable-behavior.svg",u=JSON.parse('{"title":"Agree on behavior before task execution","description":"","frontmatter":{"title":"Agree on behavior before task execution"},"headers":[],"relativePath":"workflows/specify-observable-behavior.md","filePath":"workflows/specify-observable-behavior.md"}'),r={name:"workflows/specify-observable-behavior.md"};function l(n,e,c,h,p,d){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="agree-on-behavior-before-task-execution" tabindex="-1">Agree on behavior before task execution <a class="header-anchor" href="#agree-on-behavior-before-task-execution" aria-label="Permalink to &quot;Agree on behavior before task execution&quot;">​</a></h1><p>This is a focused procedure. For its place in a larger workflow, see <a href="/projects/ai-skills/workflows/plan-a-project.html">Plan a project or feature</a>.</p><p>An agreed direction still leaves observable behavior or acceptance criteria open.</p><p><strong>Finish with:</strong> A compact specification with testable criteria and explicit exclusions.</p><h2 id="read-the-diagram" tabindex="-1">Read the diagram <a class="header-anchor" href="#read-the-diagram" aria-label="Permalink to &quot;Read the diagram&quot;">​</a></h2><p><img src="'+i+'" alt="Agree on behavior before task execution: suggested skill handoffs with approval stops where applicable."></p><p><a href="/projects/ai-skills/diagrams/specify-observable-behavior.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/specify-observable-behavior.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/specify-observable-behavior.json">Editable candidate</a></p><p>Arrows show this suggested sequence, not declared <code>requires</code> dependencies. Approval arrows are conditional. Declining a gate stops that branch without authorizing its writes. The numbered steps below are the text equivalent of the diagram.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Use a trusted project and follow its instructions. Confirm the requested scope, installed skills, runtime tools, and any required workspace or approval. This selection includes the catalogued instruction requirements <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a>. Resolve them before use.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Inspect agreed decisions.</strong> <a href="/projects/ai-skills/skills/specify.html"><code>specify</code></a> provides the guidance for this step.</li><li><strong>Resolve behavior questions.</strong> <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a> provides the guidance for this step.</li><li><strong>Define acceptance criteria.</strong> <a href="/projects/ai-skills/skills/specify.html"><code>specify</code></a> provides the guidance for this step.</li><li><strong>Record scope and test limits.</strong> <a href="/projects/ai-skills/skills/specify.html"><code>specify</code></a> provides the guidance for this step.</li></ol><h2 id="where-to-stop" tabindex="-1">Where to stop <a class="header-anchor" href="#where-to-stop" aria-label="Permalink to &quot;Where to stop&quot;">​</a></h2><p>Stop at the specification. Do not convert unresolved questions into invented requirements or treat the document as implementation authority.</p><h2 id="optional-branches" tabindex="-1">Optional branches <a class="header-anchor" href="#optional-branches" aria-label="Permalink to &quot;Optional branches&quot;">​</a></h2><ul><li>Choose <a href="/projects/ai-skills/skills/plan-tasks.html"><code>plan-tasks</code></a> when the scope or specification is clear enough to divide into bounded pieces of work.</li><li>Choose <a href="/projects/ai-skills/skills/tdd.html"><code>tdd</code></a> when you explicitly want test-first feature or bug work, or integration-test slices through public behavior.</li></ul><p>Optional branches are not prerequisites or permission to launch another phase. You can omit them or stop at the stated result. See <a href="/projects/ai-skills/reference/relationships.html">relationship types</a> for the distinction.</p>',17)])])}const b=a(r,[["render",l]]);export{u as __pageData,b as default};
